    if len(rec) < 3:
        return None
    rec = sorted(rec, key=lambda x: x["obj_ts"])[-3:]
    e = (rec[0]["err"] * 1.0 + rec[1]["err"] * 2.0 + rec[2]["err"] * 3.0) / 6.0
